import type { TransactionStatus } from '~/client';
import type { BadgeVariants } from '~/components/ui/badge/index';

interface TransactionStatusEntry {
  label: string;
  variant: BadgeVariants;
}

// Key order defines the user-visible filter order (taken from the former transactionsStatuses select list).
// `UNKNOWN` was missing from that hand-written list; deriving the list below restores it (intended).
export const transactionStatusBadge: Record<TransactionStatus, TransactionStatusEntry> = {
  PENDING: { label: 'Pending', variant: 'default' },
  SCHEDULED: { label: 'Scheduled', variant: 'default' },
  COMPLETED: { label: 'Completed', variant: 'success' },
  FAILED: { label: 'Failed', variant: 'destructive' },
  CANCELED: { label: 'Canceled', variant: 'destructive' },
  SKIPPED: { label: 'Skipped', variant: 'warning' },
  REVERSED: { label: 'Reversed', variant: 'warning' },
  UNKNOWN: { label: 'Unknown', variant: 'warning' },
};

// Fallback for a status the client doesn't know yet (backend added a new enum value).
// TransactionStatus keys are UPPERCASE, so snakeCaseToCapitalizedCase doesn't fit — fall back to the UNKNOWN sentinel.
export function getTransactionStatusBadge(status: TransactionStatus): TransactionStatusEntry {
  return transactionStatusBadge[status] ?? transactionStatusBadge.UNKNOWN;
}

export const transactionsStatuses: SelectItem<TransactionStatus>[] = Object.entries(transactionStatusBadge).map(
  ([value, { label }]) => ({ value: value as TransactionStatus, name: label })
);
